import{_ as l,a0 as c,w as n,s as p,ao as d,I as t,x as a,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Bash 腳本：正則表達式基礎篇 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 腳本：正則表達式基礎篇 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 腳本：正則表達式基礎篇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 腳本：正則表達式基礎篇 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171214 Bash Scripting- Learn to use REGEX (Basics)","title":"Bash 腳本：正則表達式基礎篇","tag":"201712","desc":""},"relativePath":"201712/20171214 Bash Scripting- Learn to use REGEX (Basics).md","filePath":"[post].md"}'),r={name:"201712/20171214 Bash Scripting- Learn to use REGEX (Basics).md"};function h(g,e,u,k,b,f){const i=c("Link");return n(),p("div",null,[e[15]||(e[15]=d('<h1 id="bash-腳本-正則表達式基礎篇" tabindex="-1">Bash 腳本：正則表達式基礎篇 <a class="header-anchor" href="#bash-腳本-正則表達式基礎篇" aria-label="Permalink to “Bash 腳本：正則表達式基礎篇”">​</a></h1><p><ruby>正則表達式<rt>Regular expressions</rt></ruby>（簡寫為 regex 或者 regexp）基本上是定義一種搜索模式的字符串，可以被用來執行“搜索”或者“搜索並替換”操作，也可以被用來驗證像密碼策略等條件。</p><p>正則表達式是一個我們可利用的非常強大的工具，並且使用正則表達式的優點是它能在幾乎所有計算機語言中被使用。所以如果你使用 Bash 腳本或者創建一個 python 程序時，我們可以使用正則表達式，或者也可以寫一個單行搜索查詢。</p><p>在這篇教程中，我們將會學習一些正則表達式的基本概念，並且學習如何在 Bash 中通過 <code>grep</code> 使用它們，但是如果你希望在其他語言如 python 或者 C 中使用它們，你只能使用正則表達式部分。那麼讓我們通過正則表達式的一個例子開始吧，</p><p>正則表達式看起來像 <code>/t[aeiou]l/</code> 這個樣子。</p><p>但這是什麼意思呢？它意味着所提到的正則表達式將尋找一個詞，它以 <code>t</code> 開始，在中間包含字母 <code>a e i o u</code> 中任意一個，並且字母 <code>l</code> 最為最後一個字符。它可以是 <code>tel</code>，<code>tal</code> 或者 <code>til</code>，可以匹配一個單獨的詞或者其它單詞像 <code>tilt</code>，<code>brutal</code> 或者 <code>telephone</code> 的一部分。</p><p>grep 使用正則表達式的語法是 <code>$ grep &quot;regex_search_term&quot; file_location</code></p><p>如果不理解，不要擔心，這只是一個例子，來展示可以利用正則表達式獲取什麼，相信我，這是最簡單的例子。我們可以從正則表達式中獲取更多。現在我們將從正則表達式基礎的開始。</p>',8)),t("ul",null,[t("li",null,[e[1]||(e[1]=a("推薦閲讀: ",-1)),s(i,{href:"http://linuxtechlab.com/useful-linux-commands-you-should-know/"},{default:o(()=>[...e[0]||(e[0]=[a("你應該知道的有用的 linux 命令",-1)])]),_:1})])]),e[16]||(e[16]=d('<h3 id="基礎的正則表示式" tabindex="-1">基礎的正則表示式 <a class="header-anchor" href="#基礎的正則表示式" aria-label="Permalink to “基礎的正則表示式”">​</a></h3><p>現在我們開始學習一些被稱為<ruby>元字符<rt>MetaCharacters</rt></ruby>的特殊字符。它們可以幫助我們創建更復雜的正則表達式搜索項。下面提到的是基本元字符的列表，</p><ul><li><code>.</code> 點將匹配任意字符</li><li><code>[ ]</code> 將匹配一個字符範圍</li><li><code>[^ ]</code> 將匹配除了括號中提到的那個之外的所有字符</li><li><code>*</code> 將匹配零個或多個前面的項</li><li><code>+</code> 將匹配一個或多個前面的項</li><li><code>?</code> 將匹配零個或一個前面的項</li><li><code>{n}</code> 將匹配 n 次前面的項</li><li><code>{n,}</code> 將匹配 n 次或更多前面的項</li><li><code>{n,m}</code> 將匹配在 n 和 m 次之間的項</li><li><code>{,m}</code> 將匹配少於或等於 m 次的項</li><li><code>\\</code> 是一個轉義字符，當我們需要在我們的搜索中包含一個元字符時使用</li></ul><p>現在我們將用例子討論所有這些元字符。</p><h4 id="點" tabindex="-1"><code>.</code> （點） <a class="header-anchor" href="#點" aria-label="Permalink to “. （點）”">​</a></h4><p>它用於匹配出現在我們搜索項中的任意字符。舉個例子，我們可以使用點如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;d.g&quot; file1</span></span></code></pre></div><p>這個正則表達式意味着我們在名為 ‘file1’ 的文件中查找的詞以 <code>d</code> 開始，以 <code>g</code>結尾，中間可以有 1 個字符的字符串。同樣，我們可以使用任意數量的點作為我們的搜索模式，如 <code>T......h</code>，這個查詢項將查找一個詞，以 <code>T</code> 開始，以 <code>h</code> 結尾，並且中間可以有任意 6 個字符。</p><h4 id="" tabindex="-1"><code>[ ]</code> <a class="header-anchor" href="#" aria-label="Permalink to “[ ]”">​</a></h4><p>方括號用於定義字符範圍。例如，我們需要搜索一些特別的單詞而不是匹配任何字符，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;N[oen]n&quot; file2</span></span></code></pre></div><p>這裏，我們正尋找一個單詞，以 <code>N</code>開頭，以 <code>n</code> 結尾，並且中間只能有 <code>o</code>、<code>e</code> 或者 <code>n</code> 中的一個。 在方括號中我們可以提到單個到任意數量的字符。</p><p>我們在方括號中也可以定義像 <code>a-e</code>或者 <code>1-18</code> 作為匹配字符的列表。</p><h4 id="-1" tabindex="-1"><code>[^ ]</code> <a class="header-anchor" href="#-1" aria-label="Permalink to “[^ ]”">​</a></h4><p>這就像正則表達式的 not 操作。當使用 <code>[^ ]</code> 時，它意味着我們的搜索將包括除了方括號內提到的所有字符。例如，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;St[^1-9]d&quot; file3</span></span></code></pre></div><p>這意味着我們可以擁有所有這樣的單詞，它們以 <code>St</code> 開始，以字母 <code>d</code> 結尾，並且不得包含從 <code>1</code> 到 <code>9</code> 的任何數字。</p><p>到現在為止，我們只使用了僅需要在中間查找單個字符的正則表達式的例子，但是如果我們需要更多字符該怎麼辦呢。假設我們需要找到以一個字符開頭和結尾的所有單詞，並且在中間可以有任意數量的字符。這就是我們使用乘數元字符如 <code>+</code> <code>*</code> 與 <code>?</code> 的地方。</p><p><code>{n}</code>、<code>{n,m}</code>、<code>{n,}</code> 或者 <code>{,m}</code> 也是可以在我們的正則表達式項中使用的其他乘數元字符。</p><h4 id="星號" tabindex="-1"><code>*</code> (星號) <a class="header-anchor" href="#星號" aria-label="Permalink to “* (星號)”">​</a></h4><p>以下示例匹配字母 <code>k</code> 的任意出現次數，包括一次沒有：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;lak*&quot; file4</span></span></code></pre></div><p>它意味着我們可以匹配到 <code>lake</code>、<code>la</code> 或者 <code>lakkkk</code>。</p><h4 id="-2" tabindex="-1"><code>+</code> <a class="header-anchor" href="#-2" aria-label="Permalink to “+”">​</a></h4><p>以下模式要求字符串中的字母 <code>k</code> 至少被匹配到一次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;lak+&quot; file5</span></span></code></pre></div><p>這裏 <code>k</code> 在我們的搜索中至少需要發生一次，所以我們的結果可以為 <code>lake</code> 或者 <code>lakkkk</code>，但不能是 <code>la</code>。</p><h4 id="-3" tabindex="-1"><code>?</code> <a class="header-anchor" href="#-3" aria-label="Permalink to “?”">​</a></h4><p>在以下模式匹配中</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;ba?b&quot; file6</span></span></code></pre></div><p>匹配字符串 <code>bb</code> 或 <code>bab</code>，使用 <code>?</code> 乘數，我們可以有一個或零個字符的出現。</p><h4 id="非常重要的提示" tabindex="-1">非常重要的提示 <a class="header-anchor" href="#非常重要的提示" aria-label="Permalink to “非常重要的提示”">​</a></h4><p>當使用乘數時這是非常重要的，假設我們有一個正則表達式</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;S.*l&quot; file7</span></span></code></pre></div><p>我們得到的結果是 <code>small</code>、<code>silly</code>，並且我們也得到了 <code>Shane is a little to play ball</code>。但是為什麼我們得到了 <code>Shane is a little to play ball</code>？我們只是在搜索中尋找單詞，為什麼我們得到了整個句子作為我們的輸出。</p><p>這是因為它滿足我們的搜索標準，它以字母 <code>s</code> 開頭，中間有任意數量的字符並以字母 <code>l</code> 結尾。那麼，我們可以做些什麼來糾正我們的正則表達式來只是得到單詞而不是整個句子作為我們的輸出。</p><p>我們在正則表達式中需要增加 <code>?</code> 元字符，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;S.*?l&quot; file7</span></span></code></pre></div><p>這將會糾正我們正則表達式的行為。</p><h4 id="-4" tabindex="-1"><code>\\</code> <a class="header-anchor" href="#-4" aria-label="Permalink to “\\”">​</a></h4><p><code>\\</code> 是當我們需要包含一個元字符或者對正則表達式有特殊含義的字符的時候來使用。例如，我們需要找到所有以點結尾的單詞，所以我們可以使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &quot;S.*\\\\.&quot; file8</span></span></code></pre></div><p>這將會查找和匹配所有以一個點字符結尾的詞。</p><p>通過這篇基本正則表達式教程，我們現在有一些關於正則表達式如何工作的基本概念。在我們的下一篇教程中，我們將學習一些高級的正則表達式的概念。同時儘可能多地練習，創建正則表達式並試着儘可能多的在你的工作中加入它們。如果有任何疑問或問題，您可以在下面的評論區留言。</p><hr>',45)),t("p",null,[e[3]||(e[3]=a("via: ",-1)),s(i,{href:"http://linuxtechlab.com/bash-scripting-learn-use-regex-basics/"},{default:o(()=>[...e[2]||(e[2]=[a("http://linuxtechlab.com/bash-scripting-learn-use-regex-basics/",-1)])]),_:1})]),t("p",null,[e[7]||(e[7]=a("作者：",-1)),s(i,{href:"http://linuxtechlab.com/author/shsuain/"},{default:o(()=>[...e[4]||(e[4]=[a("SHUSAIN",-1)])]),_:1}),e[8]||(e[8]=a(" 譯者：",-1)),s(i,{href:"https://github.com/kimii"},{default:o(()=>[...e[5]||(e[5]=[a("kimii",-1)])]),_:1}),e[9]||(e[9]=a(" 校對：",-1)),s(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[6]||(e[6]=[a("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=a("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[10]||(e[10]=[a("LCTT",-1)])]),_:1}),e[13]||(e[13]=a(" 原創編譯，",-1)),s(i,{href:"https://linux.cn/"},{default:o(()=>[...e[11]||(e[11]=[a("Linux中國",-1)])]),_:1}),e[14]||(e[14]=a(" 榮譽推出",-1))])])}const C=l(r,[["render",h]]);export{y as __pageData,C as default};
